import {wheelBoneControls} from './vehicle-wheel-bones-editor.js';
import {wheelNumbers} from './vehicle-config.js';
const names={inertia:'회전 관성 (kg·m²)',radius:'반지름 (m)',width:'폭 (m)',restLength:'서스펜션 길이 (m)',travel:'최대 이동 (m)',stiffness:'강성',compression:'압축 감쇠',relaxation:'복원 감쇠',maxForce:'최대 서스펜션 힘 (N)',friction:'타이어 마찰',sideFriction:'측면 강성',steer:'조향 비율',drive:'구동',brake:'브레이크',handbrake:'주차 브레이크'};
export function vehicleWheelControls(wheels,attrs,esc,{disabled=false}={}){const off=disabled?' disabled':'';return `<div class="vehicle-wheels">${wheels.map((w,index)=>{const attr=key=>`${attrs} data-wheel-index="${index}" data-wheel-key="${key}"`;return `<details data-vehicle-wheel="${index}"><summary>${index+1}. ${esc(w.name)}</summary><div class="component-property"><label>이름</label><input value="${esc(w.name)}" maxlength="80" ${attr('name')} aria-label="휠 ${index+1} 이름"${off}></div><div class="component-property"><label>차체 기준 위치 (m)</label><div class="component-vector">${w.position.map((v,i)=>`<label><em>${['X','Y','Z'][i]}</em><input type="number" value="${v}" step=".05" min="-10000" max="10000" ${attr('position')} data-wheel-axis="${i}" aria-label="휠 ${index+1} 위치 ${['X','Y','Z'][i]}"${off}></label>`).join('')}</div></div>${Object.entries(names).map(([key,label])=>`<div class="component-property"><label>${label}</label><input type="${key in wheelNumbers?'number':'checkbox'}" ${key in wheelNumbers?`value="${w[key]??(key==='inertia'?1.2:'')}" min="${wheelNumbers[key][0]}" max="${wheelNumbers[key][1]}" step="${key==='inertia'?'any':'.05'}"`:w[key]?'checked':''} ${attr(key)} aria-label="휠 ${index+1} ${label}"${off}></div>`).join('')}${wheelBoneControls(w,attr,esc,off)}<button ${attrs} data-wheel-remove="${index}"${off}>휠 삭제</button></details>`;}).join('')}<button ${attrs} data-wheel-add${off}>휠 추가</button></div>`;}
